1	// fare-desk：照費率表算票價。
2	import { readFileSync } from 'node:fs';
3	
4	const table = new URL('../data/rates.csv', import.meta.url);
5	const rows = readFileSync(table, 'utf8').trim().split('\n')
6	  .slice(1).map((line) => line.split(','));
7	
8	// 回傳某一區的票價；兒童半價，不足一元算一元。
9	export function fare(zone, child = false) {
10	  const row = rows.find(([name]) => name === zone);
11	  if (!row) throw new Error(`unknown zone: ${zone}`);
12	  const full = Number(row[1]);
13	  return child ? Math.floor(full / 2) : full;
14	}
